int _expenseRecordEstimateSize(
  ExpenseRecord object,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  var bytesCount = offsets.last;
  bytesCount += 3 + object.currency.length * 3;
  {
    final value = object.description;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  {
    final value = object.imagePath;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.name.length * 3;
  {
    final value = object.rejectionReason;
    if (value != null) {
      bytesCount += 3 + value.length * 3;
    }
  }
  bytesCount += 3 + object.status.length * 3;
  return bytesCount;
}

void _expenseRecordSerialize(
  ExpenseRecord object,
  IsarWriter writer,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  writer.writeLong(offsets[0], object.adminId);
  writer.writeDouble(offsets[1], object.amount);
  writer.writeLong(offsets[2], object.categoryId);
  writer.writeDateTime(offsets[3], object.createdAt);
  writer.writeString(offsets[4], object.currency);
  writer.writeDateTime(offsets[5], object.date);
  writer.writeString(offsets[6], object.description);
  writer.writeString(offsets[7], object.imagePath);
  writer.writeString(offsets[8], object.name);
  writer.writeString(offsets[9], object.rejectionReason);
  writer.writeDateTime(offsets[10], object.reviewedAt);
  writer.writeString(offsets[11], object.status);
  writer.writeDateTime(offsets[12], object.submittedAt);
  writer.writeDateTime(offsets[13], object.updatedAt);
}

ExpenseRecord _expenseRecordDeserialize(
  Id id,
  IsarReader reader,
  List<int> offsets,
  Map<Type, List<int>> allOffsets,
) {
  final object = ExpenseRecord();
  object.adminId = reader.readLongOrNull(offsets[0]);
  object.amount = reader.readDouble(offsets[1]);
  object.categoryId = reader.readLong(offsets[2]);
  object.createdAt = reader.readDateTime(offsets[3]);
  object.currency = reader.readString(offsets[4]);
  object.date = reader.readDateTime(offsets[5]);
  object.description = reader.readStringOrNull(offsets[6]);
  object.id = id;
  object.imagePath = reader.readStringOrNull(offsets[7]);
  object.name = reader.readString(offsets[8]);
  object.rejectionReason = reader.readStringOrNull(offsets[9]);
  object.reviewedAt = reader.readDateTimeOrNull(offsets[10]);
  object.status = reader.readString(offsets[11]);
  object.submittedAt = reader.readDateTimeOrNull(offsets[12]);
  object.updatedAt = reader.readDateTime(offsets[13]);
  return object;
}

